        ---@Guide walkthrough
        -- Shown above the fish list when the guide is opened. Leave a line empty
        -- or delete it and it simply is not drawn.
        ["GUIDE_HOW"]                    = "How it works",
        ["GUIDE_TIPS"]                   = "Good to know",
        ["GUIDE_INTRO"]                  =
        "Fishing is one continuous job rather than a set of separate tasks: you take a quest, you catch what it asks for, and you sell the rest. Everything below is the whole loop, and the fish it can hand you are listed underneath.",
        ["GUIDE_STEP_1"]                 =
        "Pick a quest from this panel. It names the fish you have to bring in, the level you need and what it pays.",
        ["GUIDE_STEP_2"]                 =
        "Stock up in the Shop first. A rod is the only thing you truly need, but hooks, reels, lines and bait all make the catch easier.",
        ["GUIDE_STEP_3"]                 =
        "Open the tackle box and fit your gear. Bait is never required — it just makes the fish that favour it far likelier to bite, and each fish below names its favourite.",
        ["GUIDE_STEP_4"]                 =
        "Head to the water and cast facing it. DEPTH is what decides who is down there, and the prompt tells you how deep the water in front of you is before you cast. Deeper water holds rarer and bigger fish.",
        ["GUIDE_STEP_5"]                 =
        "Wait for the bite and hook it in time. Then reel it in: keep the line tension out of the red, pull to the side when told and hold steady while the fish runs.",
        ["GUIDE_STEP_6"]                 =
        "Keep fishing until the quest fish are in your bag, then sell the catch back at the Shop to collect the money.",
        ["GUIDE_TIP_1"]                  =
        "Levelling up makes the reel-in easier, raises your chance of an extra fish per cast, and shortens the wait for a bite.",
        ["GUIDE_TIP_2"]                  =
        "Nothing is ever impossible, only unlikely. The wrong depth or the wrong bait makes a fish rare rather than unreachable, so a shallow-water marlin is a story worth telling.",
        ["GUIDE_TIP_5"]                  =
        "Rods wear out and snap. Carry a spare if you are fishing far from the shop.",
        ["GUIDE_TIP_3"]                  =
        "You can invite others: the whole group works the same quest, and the leader picks it.",
        ["GUIDE_TIP_4"]                  =
        "The Statistics tab tracks the daily and season rankings, and the top three are paid when each one resets.",
