        ---@Guide tabs
        ["GUIDE_TAB_BASICS"]             = "Basics",
        ["GUIDE_TAB_FISH"]               = "Fish",
        ["GUIDE_TAB_WAYS"]               = "Ways to fish",
        ["GUIDE_TAB_COOK"]               = "Cooking",
        ["GUIDE_TAB_EVENTS"]             = "Events",
        ["GUIDE_ZONES_ON_MAP"]           = "Tournament zones on your map",

        ---@Guide · other ways to fish
        ["GUIDE_WAY_BOAT_T"]             = "Renting a boat",
        ["GUIDE_WAY_BOAT_1"]             =
        "The deep water is where the rare fish live, and you cannot wade to it. Rent a boat from the same panel you take quests in.",
        ["GUIDE_WAY_BOAT_2"]             =
        "A rental runs on a clock and you are warned before it ends. Bring the boat back to the dock and you get part of the price back.",
        ["GUIDE_WAY_BOAT_3"]             =
        "Anchor with the anchor key before you cast. A drifting boat takes your line somewhere you did not aim it.",

        ["GUIDE_WAY_TRAP_T"]             = "Crab traps",
        ["GUIDE_WAY_TRAP_1"]             =
        "Passive fishing. Use a crab trap over deep water: the cage sinks, a buoy floats above it, and a blip goes on your map.",
        ["GUIDE_WAY_TRAP_2"]             =
        "It does not finish, it fills. The longer it soaks the more it holds, up to a cap, so when to pull it is your decision.",
        ["GUIDE_WAY_TRAP_3"]             =
        "Hauling one can break the cage. Dismantling it on purpose is the safer way to get it back.",
        ["GUIDE_WAY_TRAP_4"]             =
        "Leave one out too long and it rots away with everything inside it. You are warned before that happens.",

        ["GUIDE_WAY_NET_T"]              = "Trawl nets",
        ["GUIDE_WAY_NET_1"]              =
        "The boat is the tool. Use a net while sitting at the helm of a rented boat and it streams off the stern.",
        ["GUIDE_WAY_NET_2"]              =
        "A net fills by DISTANCE SAILED, not by time. Parked is nothing; there is a sweet spot of speed where it fills fastest.",
        ["GUIDE_WAY_NET_3"]              =
        "Drive too fast, or through water too shallow, and the net tears. A torn net is a lost net.",
        ["GUIDE_WAY_NET_4"]              =
        "Nets scoop what is there, so the fish come up small. It is volume rather than trophies.",

        ["GUIDE_WAY_SPEAR_T"]            = "Spearfishing",
        ["GUIDE_WAY_SPEAR_1"]            =
        "The only fishing you do IN the water, and it takes sharks and nothing else. No rod will ever land one.",
        ["GUIDE_WAY_SPEAR_2"]            =
        "Sharks only exist while you have a shark hunt accepted. Take it from the job ped and a zone is marked on your map.",
        ["GUIDE_WAY_SPEAR_3"]            =
        "Right mouse to aim, left to fire. Every shot spends a spear: a miss is gone, and a hit gives it back about half the time.",
        ["GUIDE_WAY_SPEAR_4"]            =
        "A dive tank is optional. Without one you have your own lungs, which is tight but enough — the tank buys comfort, not access.",

        ---@Guide · cooking
        ["GUIDE_COOK_FIRE_T"]            = "Campfires",
        ["GUIDE_COOK_FIRE_1"]            =
        "Use a log to build a fire on open ground. Not on roads, not indoors, not on the water — sand and grass are what it wants.",
        ["GUIDE_COOK_FIRE_2"]            =
        "Interact with the fire to thread a fish onto a skewer. The camera drops onto it and your mouse turns the fish.",
        ["GUIDE_COOK_FIRE_3"]            =
        "Keep turning it. The side facing the flames chars if you leave it, and enough charring ruins the fish however well the rest went.",
        ["GUIDE_COOK_FIRE_4"]            =
        "Take it off in the green window for a cooked skewer. Leave it and it burns — still food, worth a quarter as much.",

        ["GUIDE_COOK_BOAT_T"]            = "The espeto boat",
        ["GUIDE_COOK_BOAT_1"]            =
        "A sardine grill on a beached boat, carried in your bag. Set it down on dry land and you are stood behind the counter.",
        ["GUIDE_COOK_BOAT_2"]            =
        "Every raw skewer you carry appears on the rack beside you. Drag one onto the coals, right click to turn it, drag it back off when it is done.",
        ["GUIDE_COOK_BOAT_3"]            =
        "Click the coals to look straight down at them and click away to stand back up. You can only drag from the close view.",
        ["GUIDE_COOK_BOAT_4"]            =
        "Customers walk up and ask for skewers. Drag a cooked one onto them to sell it. Serve them before they lose patience.",

        ---@Guide · events
        ["GUIDE_EV_TOURN_T"]             = "Tournaments",
        ["GUIDE_EV_TOURN_1"]             =
        "A stretch of water opens for a set time and everyone fishing inside it is scored. Two boards: the single heaviest fish, and the most fish landed.",
        ["GUIDE_EV_TOURN_2"]             =
        "The top three of each board are paid when it closes. Use the map button above to see every stretch of water one can open on.",
        ["GUIDE_EV_TOURN_3"]             =
        "Only what you catch inside the circle counts, and only while it is running.",

        ["GUIDE_EV_GOLD_T"]              = "Golden zones",
        ["GUIDE_EV_GOLD_1"]              =
        "Every so often a patch of open water starts fishing far better than usual. A gold star lands on your map and everyone is told.",
        ["GUIDE_EV_GOLD_2"]              =
        "Nobody competes and nobody loses. Blanks are rarer and the good fish come up more often for as long as it lasts.",
        ["GUIDE_EV_GOLD_3"]              =
        "Traps and nets inside one get the same treatment, so it is worth moving your gear as well as yourself.",

        ["GUIDE_EV_CREW_T"]              = "Fishing as a crew",
        ["GUIDE_EV_CREW_1"]              =
        "Invite people standing near you and the whole crew works the same quest. The leader is the one who picks it.",
        ["GUIDE_EV_CREW_2"]              =
        "Everyone's catches count toward it, and everyone is paid when it is done.",

        ["GUIDE_EV_RANK_T"]              = "Rankings",
        ["GUIDE_EV_RANK_1"]              =
        "The Statistics tab keeps a daily and a season board. The top three are paid each time one resets.",
        ["GUIDE_EV_RANK_2"]              =
        "Achievements track the milestones alongside them: every species caught, trophies landed, and fish put back.",

