        ["COOK_LEFT_FIRE"]                  = "Ti sei allontanato dal fuoco.",
        ["COOK_ALREADY"]                    = "Hai già qualcosa sul fuoco.",
        ["COOK_NO_FISH"]                    = "Non ce l'hai più.",
        ["COOK_FAILED"]                     = "Non si e cotto.",
        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "La pesca è un mestiere unico e continuo, non una serie di compiti separati: prendi un incarico, peschi quello che chiede e vendi il resto. Qui sotto trovi l'intero ciclo, e sotto ancora i pesci che può darti.",
        ["GUIDE_STEP_1"]                     = "Scegli un incarico da questo pannello. Ti dice quale pesce portare, il livello richiesto e quanto paga.",
        ["GUIDE_STEP_2"]                     = "Riforniti prima nel Negozio. La canna è l'unica cosa davvero indispensabile, ma ami, mulinelli, fili ed esche rendono tutto più facile.",
        ["GUIDE_STEP_3"]                     = "Apri la cassetta e monta l'attrezzatura. L'esca non è mai obbligatoria: rende molto più probabile che abbocchi il pesce che la preferisce, e ogni pesce qui sotto indica la sua.",
        ["GUIDE_STEP_4"]                     = "Vai in riva all'acqua e lancia guardandola. È la PROFONDITÀ a decidere chi c'è là sotto, e il messaggio te la indica prima del lancio. Più è profonda, più i pesci sono rari e grossi.",
        ["GUIDE_STEP_5"]                     = "Aspetta l'abboccata e ferra in tempo. Poi recupera: tieni la tensione fuori dal rosso, tira di lato quando te lo dice e resta fermo mentre il pesce scappa.",
        ["GUIDE_STEP_6"]                     = "Continua finché non hai in borsa i pesci dell'incarico, poi vendi il pescato al Negozio per incassare.",
        ["GUIDE_TIP_1"]                      = "Salire di livello rende il recupero più facile, aumenta la probabilità di un pesce extra per lancio e accorcia l'attesa dell'abboccata.",
        ["GUIDE_TIP_2"]                      = "Niente è mai impossibile, solo improbabile. La profondità o l'esca sbagliata rendono un pesce raro, non irraggiungibile: un marlin in acqua bassa è una storia da raccontare.",
        ["GUIDE_TIP_5"]                      = "Le canne si consumano e si spezzano. Portane una di scorta se peschi lontano dal negozio.",
        ["GUIDE_TIP_3"]                      = "Puoi invitare altri: tutto il gruppo lavora allo stesso incarico, e lo sceglie il capo.",
        ["GUIDE_TIP_4"]                      = "La scheda Statistiche segue le classifiche giornaliera e stagionale, e i primi tre vengono pagati a ogni azzeramento.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "PIENA",
        ["NORMAL"]                           = "NORMALE",
        ["LOW"]                              = "BASSA",
        ["CRITICAL"]                         = "CRITICA",
        ["EMPTY"]                            = "VUOTA",
        ["WARNING_OXYGEN"]                   = "La bombola è quasi vuota — resta il 10%",
        ["GUIDE_TAB_BASICS"]                 = "Basi",
        ["GUIDE_TAB_FISH"]                   = "Pesci",
        ["GUIDE_TAB_WAYS"]                   = "Modi di pescare",
        ["GUIDE_TAB_COOK"]                   = "Cucina",
        ["GUIDE_TAB_EVENTS"]                 = "Eventi",
        ["GUIDE_ZONES_ON_MAP"]               = "Zone dei tornei sulla tua mappa",
        ["GUIDE_WAY_BOAT_T"]                 = "Noleggiare una barca",
        ["GUIDE_WAY_BOAT_1"]                 = "I pesci rari vivono in acqua profonda, e a piedi non ci arrivi. Noleggia una barca dallo stesso pannello degli incarichi.",
        ["GUIDE_WAY_BOAT_2"]                 = "Il noleggio ha un tempo e ti avvisa prima che scada. Riporta la barca al molo e recuperi parte del prezzo.",
        ["GUIDE_WAY_BOAT_3"]                 = "Getta l'ancora prima di lanciare. Una barca alla deriva porta la lenza dove non hai mirato.",
        ["GUIDE_WAY_TRAP_T"]                 = "Nasse per granchi",
        ["GUIDE_WAY_TRAP_1"]                 = "Pesca passiva. Usa una nassa su acqua profonda: la gabbia affonda, una boa resta a galla e ti compare un segnalino sulla mappa.",
        ["GUIDE_WAY_TRAP_2"]                 = "Non finisce, si riempie. Più resta giù più contiene, fino a un limite, quindi quando tirarla su lo decidi tu.",
        ["GUIDE_WAY_TRAP_3"]                 = "Tirarla su può rompere la gabbia. Smontarla di proposito è il modo più sicuro per riaverla.",
        ["GUIDE_WAY_TRAP_4"]                 = "Se la lasci troppo marcisce con tutto quello che contiene. Vieni avvisato prima che accada.",
        ["GUIDE_WAY_NET_T"]                  = "Reti a strascico",
        ["GUIDE_WAY_NET_1"]                  = "Qui l'attrezzo è la barca. Usa una rete seduto al timone di una barca noleggiata e esce da poppa.",
        ["GUIDE_WAY_NET_2"]                  = "La rete si riempie per DISTANZA NAVIGATA, non per tempo. Ferma non prende nulla, e c'è una velocità ideale in cui rende di più.",
        ["GUIDE_WAY_NET_3"]                  = "Se vai troppo veloce, o in acqua troppo bassa, la rete si strappa. Una rete strappata è una rete persa.",
        ["GUIDE_WAY_NET_4"]                  = "La rete raccoglie quello che trova, quindi i pesci escono piccoli. È quantità, non trofei.",
        ["GUIDE_WAY_SPEAR_T"]                = "Pesca subacquea",
        ["GUIDE_WAY_SPEAR_1"]                = "L'unica pesca che fai IN acqua, e prende solo squali. Nessuna canna ne tirerà mai su uno.",
        ["GUIDE_WAY_SPEAR_2"]                = "Gli squali esistono solo mentre hai una caccia accettata. Prendila dall'NPC e ti viene segnata una zona sulla mappa.",
        ["GUIDE_WAY_SPEAR_3"]                = "Tasto destro per mirare, sinistro per sparare. Ogni colpo consuma un arpione: se sbagli lo perdi, se colpisci lo recuperi circa una volta su due.",
        ["GUIDE_WAY_SPEAR_4"]                = "La bombola è facoltativa. Senza hai i tuoi polmoni, che bastano appena — la bombola dà comodità, non accesso.",
        ["GUIDE_COOK_FIRE_T"]                = "Falò",
        ["GUIDE_COOK_FIRE_1"]                = "Usa un ceppo per accendere un falò su terreno aperto. Non sull'asfalto, non al chiuso, non sull'acqua: vuole sabbia o erba.",
        ["GUIDE_COOK_FIRE_2"]                = "Interagisci col fuoco per infilzare un pesce sullo spiedo. La telecamera scende su di esso e il mouse lo fa girare.",
        ["GUIDE_COOK_FIRE_3"]                = "Continua a girarlo. Il lato rivolto alle fiamme si carbonizza se lo lasci, e abbastanza bruciatura rovina il pesce comunque.",
        ["GUIDE_COOK_FIRE_4"]                = "Toglilo nella finestra verde e hai uno spiedo cotto. Se lo lasci brucia: è ancora cibo, ma vale un quarto.",
        ["GUIDE_COOK_BOAT_T"]                = "La barca degli spiedini",
        ["GUIDE_COOK_BOAT_1"]                = "Una griglia per sardine su una barca arenata, che porti nello zaino. Appoggiala su terra ferma e ti ritrovi dietro al bancone.",
        ["GUIDE_COOK_BOAT_2"]                = "Tutti gli spiedi crudi che porti compaiono sulla rastrelliera accanto. Trascinane uno sulla brace, tasto destro per girarlo, e toglilo quando è pronto.",
        ["GUIDE_COOK_BOAT_3"]                = "Clicca sulla brace per guardarla dall'alto e clicca fuori per rialzarti. Puoi trascinare solo dalla vista ravvicinata.",
        ["GUIDE_COOK_BOAT_4"]                = "Arrivano clienti a chiedere spiedini. Trascinane uno cotto su di loro per venderlo, prima che si stanchino di aspettare.",
        ["GUIDE_EV_TOURN_T"]                 = "Tornei",
        ["GUIDE_EV_TOURN_1"]                 = "Si apre una zona d'acqua per un po' e tutti quelli che pescano dentro vengono classificati. Due classifiche: il pesce più pesante e il maggior numero di pesci.",
        ["GUIDE_EV_TOURN_2"]                 = "I primi tre di ogni classifica vengono pagati alla fine. Usa il pulsante mappa qui sopra per vedere tutte le zone dove può aprirsene uno.",
        ["GUIDE_EV_TOURN_3"]                 = "Conta solo quello che peschi dentro il cerchio, e solo mentre è attivo.",
        ["GUIDE_EV_GOLD_T"]                  = "Zone dorate",
        ["GUIDE_EV_GOLD_1"]                  = "Ogni tanto un tratto di mare aperto inizia a rendere molto di più. Compare una stella dorata sulla mappa e vengono avvisati tutti.",
        ["GUIDE_EV_GOLD_2"]                  = "Nessuno compete e nessuno perde. Si pesca a vuoto più di rado e i pesci buoni escono più spesso, finché dura.",
        ["GUIDE_EV_GOLD_3"]                  = "Nasse e reti che stanno dentro ricevono lo stesso trattamento, quindi conviene spostare anche l'attrezzatura.",
        ["GUIDE_EV_CREW_T"]                  = "Pescare in gruppo",
        ["GUIDE_EV_CREW_1"]                  = "Invita chi ti sta vicino e tutto il gruppo lavora allo stesso incarico. Lo sceglie il capo.",
        ["GUIDE_EV_CREW_2"]                  = "Quello che pesca ognuno conta per l'incarico, e alla fine vengono pagati tutti.",
        ["GUIDE_EV_RANK_T"]                  = "Classifiche",
