        ---@Guía del trabajo
        ["GUIDE_HOW"]                    = "Cómo funciona",
        ["GUIDE_TIPS"]                   = "Para tener en cuenta",
        ["GUIDE_INTRO"]                  =
        "Pescar es un solo trabajo continuo, no un conjunto de tareas separadas: agarrás una misión, pescás lo que te pide y vendés el resto. Acá abajo está todo el ciclo, y más abajo la lista de peces que podés sacar.",
        ["GUIDE_STEP_1"]                 =
        "Elegí una misión en este panel. Te dice qué peces tenés que traer, el nivel que necesitás y cuánto paga.",
        ["GUIDE_STEP_2"]                 =
        "Abastecete primero en la Tienda. Lo único imprescindible es la caña, pero anzuelos, carretes, líneas y cebos te hacen la pesca más fácil.",
        ["GUIDE_STEP_3"]                 =
        "Abrí la caja de aparejos y equipate. El cebo decide qué pica: cada pez de la lista indica cuál quiere.",
        ["GUIDE_STEP_4"]                 =
        "Andá al agua y lanzá mirando hacia ella. El agua dulce y la salada tienen peces distintos, así que fijate en la lista antes de viajar.",
        ["GUIDE_STEP_5"]                 =
        "Esperá la picada y clavá a tiempo. Después recogé: mantené la tensión de la línea fuera del rojo, tirá para el costado cuando te lo indique y aguantá firme mientras el pez corre.",
        ["GUIDE_STEP_6"]                 =
        "Seguí pescando hasta tener los peces de la misión, y después vendé la captura en la Tienda para cobrar.",
        ["GUIDE_TIP_1"]                  =
        "Subir de nivel hace la pelea mas facil, aumenta la probabilidad de sacar un pez extra por lanzada, y acorta la espera hasta la picada.",
        ["GUIDE_TIP_2"]                  =
        "Las cañas se desgastan y se rompen. Llevá una de repuesto si vas a pescar lejos de la tienda.",
        ["GUIDE_TIP_3"]                  =
        "Podés invitar a otros: todo el grupo hace la misma misión y la elige el líder.",
        ["GUIDE_TIP_4"]                  =
        "La pestaña Estadísticas lleva los rankings diario y de temporada, y el top 3 cobra cuando cada uno se reinicia.",
