        ---@Pestañas de la guía
        ["GUIDE_TAB_BASICS"]             = "Lo básico",
        ["GUIDE_TAB_FISH"]               = "Peces",
        ["GUIDE_TAB_WAYS"]               = "Formas de pescar",
        ["GUIDE_TAB_COOK"]               = "Cocina",
        ["GUIDE_TAB_EVENTS"]             = "Eventos",
        ["GUIDE_ZONES_ON_MAP"]           = "Zonas de torneo en tu mapa",

        ---@Guía · otras formas de pescar
        ["GUIDE_WAY_BOAT_T"]             = "Alquilar un bote",
        ["GUIDE_WAY_BOAT_1"]             =
        "Los peces raros viven en el agua profunda, y ahí no llegás caminando. Alquilá un bote desde el mismo panel donde agarrás las misiones.",
        ["GUIDE_WAY_BOAT_2"]             =
        "El alquiler tiene reloj y te avisa antes de que se termine. Si devolvés el bote al muelle recuperás parte de lo que pagaste.",
        ["GUIDE_WAY_BOAT_3"]             =
        "Tirá el ancla antes de lanzar. Un bote a la deriva se lleva la línea a donde vos no apuntaste.",

        ["GUIDE_WAY_TRAP_T"]             = "Trampas para cangrejo",
        ["GUIDE_WAY_TRAP_1"]             =
        "Pesca pasiva. Usá una trampa sobre agua profunda: la jaula se hunde, queda una boya arriba y te aparece la marca en el mapa.",
        ["GUIDE_WAY_TRAP_2"]             =
        "No se termina, se llena. Cuanto más tiempo está abajo más trae, hasta un tope, así que cuándo levantarla lo decidís vos.",
        ["GUIDE_WAY_TRAP_3"]             =
        "Levantarla puede romper la jaula. Desarmarla a propósito es la forma más segura de recuperarla.",
        ["GUIDE_WAY_TRAP_4"]             =
        "Si la dejás demasiado se pudre con todo lo que tiene adentro. Te avisa antes de que pase.",

        ["GUIDE_WAY_NET_T"]              = "Redes de arrastre",
        ["GUIDE_WAY_NET_1"]              =
        "Acá la herramienta es el bote. Usá una red sentado al timón de un bote alquilado y sale por la popa.",
        ["GUIDE_WAY_NET_2"]              =
        "La red se llena por DISTANCIA NAVEGADA, no por tiempo. Parado no junta nada, y hay una velocidad justa donde rinde más.",
        ["GUIDE_WAY_NET_3"]              =
        "Si vas muy rápido, o por agua muy poco profunda, la red se rompe. Una red rota es una red perdida.",
        ["GUIDE_WAY_NET_4"]              =
        "La red junta lo que hay, así que los peces salen chicos. Es cantidad, no trofeos.",

        ["GUIDE_WAY_SPEAR_T"]            = "Pesca submarina",
        ["GUIDE_WAY_SPEAR_1"]            =
        "La única pesca que hacés DENTRO del agua, y solo saca tiburones. Ninguna caña va a sacar uno.",
        ["GUIDE_WAY_SPEAR_2"]            =
        "Los tiburones solo existen mientras tengas una cacería aceptada. Agarrala del NPC y se te marca una zona en el mapa.",
        ["GUIDE_WAY_SPEAR_3"]            =
        "Botón derecho para apuntar, izquierdo para disparar. Cada tiro gasta un arpón: si errás lo perdés, si acertás lo recuperás la mitad de las veces.",
        ["GUIDE_WAY_SPEAR_4"]            =
        "El tanque de buceo es opcional. Sin él tenés tus propios pulmones, que alcanzan justo — el tanque da comodidad, no acceso.",

        ---@Guía · cocina
        ["GUIDE_COOK_FIRE_T"]            = "Fogatas",
        ["GUIDE_COOK_FIRE_1"]            =
        "Usá un tronco para armar una fogata en terreno abierto. No sobre asfalto, ni bajo techo, ni en el agua: arena y pasto es lo que busca.",
        ["GUIDE_COOK_FIRE_2"]            =
        "Interactuá con el fuego para clavar un pez en el pincho. La cámara baja sobre él y el mouse lo hace girar.",
        ["GUIDE_COOK_FIRE_3"]            =
        "Giralo seguido. El lado que mira a las llamas se quema si lo dejás, y con suficiente quemado el pez se arruina igual.",
        ["GUIDE_COOK_FIRE_4"]            =
        "Sacalo en la ventana verde y tenés un pincho cocido. Si lo dejás se quema: sigue siendo comida, pero vale la cuarta parte.",

        ["GUIDE_COOK_BOAT_T"]            = "El bote de espetos",
        ["GUIDE_COOK_BOAT_1"]            =
        "Una parrilla de sardinas sobre un bote varado, que llevás en la mochila. Apoyalo en tierra firme y quedás parado detrás del mostrador.",
        ["GUIDE_COOK_BOAT_2"]            =
        "Todos los pinchos crudos que lleves aparecen en el atril al lado. Arrastrá uno a las brasas, clic derecho para darlo vuelta, y sacalo cuando esté.",
        ["GUIDE_COOK_BOAT_3"]            =
        "Hacé clic en las brasas para mirarlas desde arriba y clic afuera para volver a pararte. Solo podés arrastrar desde la vista de cerca.",
        ["GUIDE_COOK_BOAT_4"]            =
        "Se acercan clientes a pedir pinchos. Arrastrales uno cocido para vendérselo, antes de que se cansen de esperar.",

        ---@Guía · eventos
        ["GUIDE_EV_TOURN_T"]             = "Torneos",
        ["GUIDE_EV_TOURN_1"]             =
        "Se abre una zona de agua por un rato y se puntúa a todos los que pescan adentro. Hay dos tablas: el pez más pesado, y la mayor cantidad.",
        ["GUIDE_EV_TOURN_2"]             =
        "Los tres primeros de cada tabla cobran cuando termina. Usá el botón de mapa de arriba para ver todas las zonas donde puede abrirse uno.",
        ["GUIDE_EV_TOURN_3"]             =
        "Solo cuenta lo que saques dentro del círculo, y solo mientras esté activo.",

        ["GUIDE_EV_GOLD_T"]              = "Zonas doradas",
        ["GUIDE_EV_GOLD_1"]              =
        "Cada tanto una zona de mar abierto empieza a rendir muchísimo más. Aparece una estrella dorada en el mapa y se avisa a todos.",
        ["GUIDE_EV_GOLD_2"]              =
        "Nadie compite y nadie pierde. Se pesca menos en vano y los peces buenos salen más seguido mientras dura.",
