        ["COOK_NO_FISH"]                    = "Vous n'avez plus ça.",
        ["COOK_FAILED"]                     = "Ca n a pas cuit.",
        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "La pêche est un seul métier continu plutôt qu'une série de tâches séparées : tu prends une mission, tu pêches ce qu'elle demande et tu vends le reste. Tout le cycle est ci-dessous, et les poissons qu'il peut te donner juste après.",
        ["GUIDE_STEP_1"]                     = "Choisis une mission dans ce panneau. Elle indique le poisson à ramener, le niveau requis et ce qu'elle rapporte.",
        ["GUIDE_STEP_2"]                     = "Fais tes courses à la Boutique d'abord. Une canne est la seule chose vraiment indispensable, mais hameçons, moulinets, lignes et appâts facilitent tout.",
        ["GUIDE_STEP_3"]                     = "Ouvre la boîte à pêche et monte ton matériel. L'appât n'est jamais obligatoire : il rend simplement bien plus probable la touche du poisson qui l'aime, et chaque poisson indique le sien.",
        ["GUIDE_STEP_4"]                     = "Va au bord de l'eau et lance en lui faisant face. C'est la PROFONDEUR qui décide qui se trouve en dessous, et le message te l'indique avant le lancer. Plus c'est profond, plus les poissons sont rares et gros.",
        ["GUIDE_STEP_5"]                     = "Attends la touche et ferre à temps. Puis remonte : garde la tension hors du rouge, tire sur le côté quand on te le dit et tiens bon quand le poisson fuit.",
        ["GUIDE_STEP_6"]                     = "Continue jusqu'à avoir les poissons de la mission dans ton sac, puis vends ta prise à la Boutique pour encaisser.",
        ["GUIDE_TIP_1"]                      = "Monter en niveau facilite la remontée, augmente les chances d'un poisson supplémentaire par lancer et raccourcit l'attente avant une touche.",
        ["GUIDE_TIP_2"]                      = "Rien n'est jamais impossible, seulement improbable. La mauvaise profondeur ou le mauvais appât rend un poisson rare, pas inaccessible : un marlin en eau peu profonde, ça se raconte.",
        ["GUIDE_TIP_5"]                      = "Les cannes s'usent et cassent. Emporte-en une de rechange si tu pêches loin de la boutique.",
        ["GUIDE_TIP_3"]                      = "Tu peux inviter d'autres joueurs : tout le groupe travaille la même mission, et c'est le chef qui la choisit.",
        ["GUIDE_TIP_4"]                      = "L'onglet Statistiques suit les classements du jour et de la saison, et le top 3 est payé à chaque remise à zéro.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "PLEINE",
        ["NORMAL"]                           = "NORMALE",
        ["LOW"]                              = "FAIBLE",
        ["CRITICAL"]                         = "CRITIQUE",
        ["EMPTY"]                            = "VIDE",
        ["WARNING_OXYGEN"]                   = "Ta bouteille est presque vide — il reste 10%",
        ["GUIDE_TAB_BASICS"]                 = "Bases",
        ["GUIDE_TAB_FISH"]                   = "Poissons",
        ["GUIDE_TAB_WAYS"]                   = "Façons de pêcher",
        ["GUIDE_TAB_COOK"]                   = "Cuisine",
        ["GUIDE_TAB_EVENTS"]                 = "Événements",
        ["GUIDE_ZONES_ON_MAP"]               = "Zones de tournoi sur ta carte",
        ["GUIDE_WAY_BOAT_T"]                 = "Louer un bateau",
        ["GUIDE_WAY_BOAT_1"]                 = "Les poissons rares vivent en eau profonde, et on n'y va pas à pied. Loue un bateau depuis le même panneau que les missions.",
        ["GUIDE_WAY_BOAT_2"]                 = "La location a un chrono et te prévient avant la fin. Ramène le bateau au ponton et tu récupères une partie du prix.",
        ["GUIDE_WAY_BOAT_3"]                 = "Jette l'ancre avant de lancer. Un bateau à la dérive emmène ta ligne là où tu ne visais pas.",
        ["GUIDE_WAY_TRAP_T"]                 = "Casiers à crabes",
        ["GUIDE_WAY_TRAP_1"]                 = "Pêche passive. Utilise un casier au-dessus d'une eau profonde : la cage coule, une bouée flotte au-dessus et un repère apparaît sur ta carte.",
        ["GUIDE_WAY_TRAP_2"]                 = "Il ne se termine pas, il se remplit. Plus il reste, plus il contient, jusqu'à un plafond : quand le relever, c'est toi qui décides.",
        ["GUIDE_WAY_TRAP_3"]                 = "Le relever peut casser la cage. Le démonter exprès est la façon la plus sûre de le récupérer.",
        ["GUIDE_WAY_TRAP_4"]                 = "Laissé trop longtemps, il pourrit avec tout ce qu'il contient. Tu es prévenu avant.",
        ["GUIDE_WAY_NET_T"]                  = "Chaluts",
        ["GUIDE_WAY_NET_1"]                  = "Ici l'outil, c'est le bateau. Utilise un filet assis à la barre d'un bateau loué et il sort par l'arrière.",
        ["GUIDE_WAY_NET_2"]                  = "Un filet se remplit à la DISTANCE PARCOURUE, pas au temps. À l'arrêt il ne prend rien, et il existe une vitesse idéale où il rend le plus.",
        ["GUIDE_WAY_NET_3"]                  = "Trop vite, ou dans une eau trop peu profonde, le filet se déchire. Un filet déchiré est un filet perdu.",
        ["GUIDE_WAY_NET_4"]                  = "Le filet ramasse ce qu'il y a, donc les poissons sortent petits. C'est du volume, pas des trophées.",
        ["GUIDE_WAY_SPEAR_T"]                = "Chasse sous-marine",
        ["GUIDE_WAY_SPEAR_1"]                = "La seule pêche que tu fais DANS l'eau, et elle ne prend que des requins. Aucune canne n'en sortira jamais un.",
        ["GUIDE_WAY_SPEAR_2"]                = "Les requins n'existent que pendant une chasse acceptée. Prends-la auprès du PNJ et une zone est marquée sur ta carte.",
        ["GUIDE_WAY_SPEAR_3"]                = "Clic droit pour viser, gauche pour tirer. Chaque tir coûte une flèche : ratée elle est perdue, réussie tu la récupères environ une fois sur deux.",
        ["GUIDE_WAY_SPEAR_4"]                = "La bouteille est facultative. Sans elle tu as tes poumons, ce qui suffit tout juste — la bouteille achète du confort, pas l'accès.",
        ["GUIDE_COOK_FIRE_T"]                = "Feux de camp",
        ["GUIDE_COOK_FIRE_1"]                = "Utilise une bûche pour faire un feu en terrain dégagé. Pas sur la route, pas à l'intérieur, pas sur l'eau : il lui faut du sable ou de l'herbe.",
        ["GUIDE_COOK_FIRE_2"]                = "Interagis avec le feu pour embrocher un poisson. La caméra descend dessus et la souris le fait tourner.",
        ["GUIDE_COOK_FIRE_3"]                = "Continue à le tourner. Le côté face aux flammes carbonise si tu le laisses, et assez de brûlé gâche le poisson quoi qu'il arrive.",
        ["GUIDE_COOK_FIRE_4"]                = "Retire-le dans la fenêtre verte et tu as une brochette cuite. Laissée trop longtemps elle brûle : ça reste de la nourriture, mais ça vaut quatre fois moins.",
        ["GUIDE_COOK_BOAT_T"]                = "Le bateau à brochettes",
        ["GUIDE_COOK_BOAT_1"]                = "Un gril à sardines sur un bateau échoué, que tu portes dans ton sac. Pose-le sur la terre ferme et tu te retrouves derrière le comptoir.",
        ["GUIDE_COOK_BOAT_2"]                = "Toutes les brochettes crues que tu portes apparaissent sur le présentoir à côté. Fais-en glisser une sur les braises, clic droit pour la tourner, et retire-la quand elle est prête.",
        ["GUIDE_COOK_BOAT_3"]                = "Clique sur les braises pour les regarder d'en haut et clique à côté pour te relever. Tu ne peux glisser que depuis la vue rapprochée.",
        ["GUIDE_COOK_BOAT_4"]                = "Des clients viennent demander des brochettes. Fais-en glisser une cuite sur eux pour la vendre, avant qu'ils ne se lassent d'attendre.",
        ["GUIDE_EV_TOURN_T"]                 = "Tournois",
        ["GUIDE_EV_TOURN_1"]                 = "Une zone d'eau s'ouvre pour un temps et tous ceux qui y pêchent sont classés. Deux tableaux : le poisson le plus lourd, et le plus grand nombre de prises.",
        ["GUIDE_EV_TOURN_2"]                 = "Le top 3 de chaque tableau est payé à la fermeture. Utilise le bouton carte ci-dessus pour voir toutes les zones où un tournoi peut s'ouvrir.",
        ["GUIDE_EV_TOURN_3"]                 = "Seul ce que tu pêches dans le cercle compte, et seulement pendant qu'il est actif.",
        ["GUIDE_EV_GOLD_T"]                  = "Zones dorées",
        ["GUIDE_EV_GOLD_1"]                  = "De temps en temps, un coin de mer se met à donner bien plus. Une étoile dorée apparaît sur la carte et tout le monde est prévenu.",
        ["GUIDE_EV_GOLD_2"]                  = "Personne ne s'affronte et personne ne perd. On pêche moins souvent dans le vide et les bons poissons sortent plus souvent, tant que ça dure.",
        ["GUIDE_EV_GOLD_3"]                  = "Les casiers et les filets qui s'y trouvent en profitent aussi, donc ça vaut le coup de déplacer ton matériel autant que toi.",
        ["GUIDE_EV_CREW_T"]                  = "Pêcher en équipe",
        ["GUIDE_EV_CREW_1"]                  = "Invite ceux qui sont près de toi et toute l'équipe travaille la même mission. C'est le chef qui la choisit.",
        ["GUIDE_EV_CREW_2"]                  = "Ce que pêche chacun compte pour la mission, et tout le monde est payé à la fin.",
        ["GUIDE_EV_RANK_T"]                  = "Classements",
        ["GUIDE_EV_RANK_1"]                  = "L'onglet Statistiques tient un classement du jour et un de la saison. Le top 3 est payé à chaque remise à zéro.",
        ["GUIDE_EV_RANK_2"]                  = "Les succès vont avec : chaque espèce pêchée, les trophées sortis et les poissons relâchés.",
        ["FOODBOAT_NO_ORDER"]                = "Cette personne n'a rien commandé",
        ["FOODBOAT_BUYER_GONE"]              = "Elle n'est plus là",
        ["FOODBOAT_BUYER_FULL"]              = "Son sac ne peut pas le prendre",
