        ["COOK_LEFT_FIRE"]                  = "Afastaste-te da fogueira.",
        ["COOK_ALREADY"]                    = "Já tens algo no fogo.",
        ["COOK_NO_FISH"]                    = "Já não tens isso.",
        ["COOK_FAILED"]                     = "Aquilo nao cozinhou.",
        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "A pesca é um ofício único e contínuo, não uma série de tarefas separadas: pegas uma missão, pescas o que ela pede e vendes o resto. Abaixo está o ciclo inteiro, e a seguir os peixes que ele te pode dar.",
        ["GUIDE_STEP_1"]                     = "Escolhe uma missão neste painel. Diz que peixe trazer, o nível necessário e quanto paga.",
        ["GUIDE_STEP_2"]                     = "Abastece-te primeiro na Loja. A cana é a única coisa mesmo indispensável, mas anzóis, carretos, linhas e iscas facilitam tudo.",
        ["GUIDE_STEP_3"]                     = "Abre a caixa de pesca e monta o equipamento. A isca nunca é obrigatória: só torna muito mais provável a mordida do peixe que gosta dela, e cada peixe indica a sua.",
        ["GUIDE_STEP_4"]                     = "Vai até à água e lança de frente para ela. É a PROFUNDIDADE que decide quem está lá em baixo, e a mensagem indica-a antes do lançamento. Mais fundo significa peixes mais raros e maiores.",
        ["GUIDE_STEP_5"]                     = "Espera pela mordida e ferra a tempo. Depois recolhe: mantém a tensão fora do vermelho, puxa para o lado quando te disserem e aguenta enquanto o peixe foge.",
        ["GUIDE_STEP_6"]                     = "Continua até teres os peixes da missão na mochila, depois vende a pescaria na Loja para receber.",
        ["GUIDE_TIP_1"]                      = "Subir de nível facilita a recolha, aumenta a hipótese de um peixe extra por lançamento e encurta a espera pela mordida.",
        ["GUIDE_TIP_2"]                      = "Nada é impossível, apenas improvável. A profundidade ou a isca erradas tornam um peixe raro, não inalcançável: um marlim em água rasa é uma história para contar.",
        ["GUIDE_TIP_5"]                      = "As canas gastam-se e partem. Leva uma sobresselente se pescares longe da loja.",
        ["GUIDE_TIP_3"]                      = "Podes convidar outros: o grupo todo trabalha a mesma missão, e é o líder que a escolhe.",
        ["GUIDE_TIP_4"]                      = "O separador Estatísticas segue os rankings diário e da temporada, e os três primeiros recebem sempre que um deles reinicia.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "CHEIA",
        ["NORMAL"]                           = "NORMAL",
        ["LOW"]                              = "BAIXA",
        ["CRITICAL"]                         = "CRÍTICA",
        ["EMPTY"]                            = "VAZIA",
        ["WARNING_OXYGEN"]                   = "A tua garrafa está quase vazia — resta 10%",
        ["GUIDE_TAB_BASICS"]                 = "Básico",
        ["GUIDE_TAB_FISH"]                   = "Peixes",
        ["GUIDE_TAB_WAYS"]                   = "Formas de pescar",
        ["GUIDE_TAB_COOK"]                   = "Cozinha",
        ["GUIDE_TAB_EVENTS"]                 = "Eventos",
        ["GUIDE_ZONES_ON_MAP"]               = "Zonas de torneio no teu mapa",
        ["GUIDE_WAY_BOAT_T"]                 = "Alugar um barco",
        ["GUIDE_WAY_BOAT_1"]                 = "Os peixes raros vivem em água funda, e lá não se chega a pé. Aluga um barco no mesmo painel das missões.",
        ["GUIDE_WAY_BOAT_2"]                 = "O aluguer tem relógio e avisa-te antes de acabar. Devolve o barco ao cais e recuperas parte do preço.",
        ["GUIDE_WAY_BOAT_3"]                 = "Lança a âncora antes de lançar a linha. Um barco à deriva leva a linha para onde não apontaste.",
        ["GUIDE_WAY_TRAP_T"]                 = "Armadilhas de caranguejo",
        ["GUIDE_WAY_TRAP_1"]                 = "Pesca passiva. Usa uma armadilha sobre água funda: a gaiola afunda, uma boia fica à superfície e aparece uma marca no teu mapa.",
        ["GUIDE_WAY_TRAP_2"]                 = "Não termina, enche-se. Quanto mais tempo ficar, mais traz, até um limite — quando a levantar decides tu.",
        ["GUIDE_WAY_TRAP_3"]                 = "Levantá-la pode partir a gaiola. Desmontá-la de propósito é a forma mais segura de a recuperar.",
        ["GUIDE_WAY_TRAP_4"]                 = "Se a deixares demasiado tempo apodrece com tudo lá dentro. És avisado antes disso acontecer.",
        ["GUIDE_WAY_NET_T"]                  = "Redes de arrasto",
        ["GUIDE_WAY_NET_1"]                  = "Aqui a ferramenta é o barco. Usa uma rede sentado ao leme de um barco alugado e ela sai pela popa.",
        ["GUIDE_WAY_NET_2"]                  = "A rede enche por DISTÂNCIA NAVEGADA, não por tempo. Parada não apanha nada, e há uma velocidade certa em que rende mais.",
        ["GUIDE_WAY_NET_3"]                  = "Depressa demais, ou em água rasa demais, e a rede rasga. Uma rede rasgada é uma rede perdida.",
        ["GUIDE_WAY_NET_4"]                  = "A rede apanha o que lá está, por isso os peixes saem pequenos. É quantidade, não troféus.",
        ["GUIDE_WAY_SPEAR_T"]                = "Pesca submarina",
        ["GUIDE_WAY_SPEAR_1"]                = "A única pesca que fazes DENTRO de água, e só apanha tubarões. Nenhuma cana vai tirar um.",
        ["GUIDE_WAY_SPEAR_2"]                = "Os tubarões só existem enquanto tiveres uma caçada aceite. Pega-a no NPC e fica marcada uma zona no teu mapa.",
        ["GUIDE_WAY_SPEAR_3"]                = "Botão direito para apontar, esquerdo para disparar. Cada tiro gasta um arpão: se falhares perde-se, se acertares recuperas cerca de metade das vezes.",
        ["GUIDE_WAY_SPEAR_4"]                = "A garrafa é opcional. Sem ela tens os teus pulmões, que chegam à justa — a garrafa dá conforto, não acesso.",
        ["GUIDE_COOK_FIRE_T"]                = "Fogueiras",
        ["GUIDE_COOK_FIRE_1"]                = "Usa um tronco para fazer uma fogueira em terreno aberto. Não no alcatrão, não dentro de edifícios, não na água: quer areia ou erva.",
        ["GUIDE_COOK_FIRE_2"]                = "Interage com o fogo para espetar um peixe. A câmara desce sobre ele e o rato fá-lo girar.",
        ["GUIDE_COOK_FIRE_3"]                = "Continua a virá-lo. O lado virado para as chamas carboniza se o deixares, e queimado que chegue estraga o peixe na mesma.",
        ["GUIDE_COOK_FIRE_4"]                = "Tira-o na janela verde e tens um espeto cozinhado. Se o deixares queima: continua a ser comida, mas vale um quarto.",
        ["GUIDE_COOK_BOAT_T"]                = "O barco dos espetos",
        ["GUIDE_COOK_BOAT_1"]                = "Uma grelha de sardinhas num barco encalhado, que levas na mochila. Pousa-o em terra firme e ficas atrás do balcão.",
        ["GUIDE_COOK_BOAT_2"]                = "Todos os espetos crus que levares aparecem no suporte ao lado. Arrasta um para as brasas, botão direito para o virar, e tira-o quando estiver pronto.",
        ["GUIDE_COOK_BOAT_3"]                = "Clica nas brasas para as ver de cima e clica fora para te levantares. Só podes arrastar da vista de perto.",
        ["GUIDE_COOK_BOAT_4"]                = "Aparecem clientes a pedir espetos. Arrasta-lhes um cozinhado para o venderes, antes que se cansem de esperar.",
        ["GUIDE_EV_TOURN_T"]                 = "Torneios",
        ["GUIDE_EV_TOURN_1"]                 = "Abre-se uma zona de água por um tempo e todos os que lá pescam são pontuados. Duas tabelas: o peixe mais pesado e a maior quantidade.",
        ["GUIDE_EV_TOURN_2"]                 = "Os três primeiros de cada tabela recebem no fim. Usa o botão de mapa acima para veres todas as zonas onde um torneio pode abrir.",
        ["GUIDE_EV_TOURN_3"]                 = "Só conta o que apanhares dentro do círculo, e só enquanto estiver ativo.",
        ["GUIDE_EV_GOLD_T"]                  = "Zonas douradas",
        ["GUIDE_EV_GOLD_1"]                  = "De vez em quando uma zona de mar aberto começa a render muito mais. Aparece uma estrela dourada no mapa e todos são avisados.",
        ["GUIDE_EV_GOLD_2"]                  = "Ninguém compete e ninguém perde. Pesca-se em vão menos vezes e os peixes bons saem mais, enquanto durar.",
        ["GUIDE_EV_GOLD_3"]                  = "As armadilhas e redes que lá estiverem recebem o mesmo, por isso compensa mover o equipamento além de te moveres a ti.",
        ["GUIDE_EV_CREW_T"]                  = "Pescar em grupo",
        ["GUIDE_EV_CREW_1"]                  = "Convida quem estiver perto de ti e o grupo todo trabalha a mesma missão. É o líder que a escolhe.",
        ["GUIDE_EV_CREW_2"]                  = "O que cada um pesca conta para a missão, e recebem todos quando estiver feita.",
        ["GUIDE_EV_RANK_T"]                  = "Classificações",
        ["GUIDE_EV_RANK_1"]                  = "O separador Estatísticas mantém uma tabela diária e uma da temporada. Os três primeiros recebem sempre que uma reinicia.",
        ["GUIDE_EV_RANK_2"]                  = "As conquistas vão ao lado: cada espécie apanhada, os troféus tirados e os peixes devolvidos.",
        ["FOODBOAT_NO_ORDER"]                = "Essa pessoa não pediu nada",
        ["FOODBOAT_BUYER_GONE"]              = "Já não está aqui",
        ["FOODBOAT_BUYER_FULL"]              = "Não lhe cabe na mochila",
