        ["COOK_TOOK_COOKED"]                = "Durch und durch gar. Ein guter Spieß.",
        ["COOK_TOOK_BURNT"]                 = "Zu lange drin gelassen. Er ist verbrannt.",
        ["COOK_LEFT_FIRE"]                  = "Du bist vom Feuer weggegangen.",
