        ["COOK_NO_FISH"]                    = "Das hast du nicht mehr.",
        ["COOK_FAILED"]                     = "Das wurde nicht gar.",
        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "Angeln ist ein einziger durchgehender Beruf und keine Reihe getrennter Aufgaben: Du nimmst einen Auftrag an, fängst was er verlangt und verkaufst den Rest. Unten steht der ganze Ablauf, darunter die Fische, die er dir bringen kann.",
        ["GUIDE_STEP_1"]                     = "Wähl einen Auftrag in diesem Panel. Er nennt den Fisch, das nötige Level und die Bezahlung.",
        ["GUIDE_STEP_2"]                     = "Deck dich zuerst im Shop ein. Nur die Rute brauchst du wirklich, aber Haken, Rollen, Schnüre und Köder machen alles leichter.",
        ["GUIDE_STEP_3"]                     = "Öffne den Angelkasten und rüste deine Ausrüstung. Köder sind nie Pflicht: Sie machen den Fisch, der sie mag, nur viel wahrscheinlicher, und bei jedem Fisch steht sein Lieblingsköder.",
        ["GUIDE_STEP_4"]                     = "Geh ans Wasser und wirf zum Wasser hin aus. Die TIEFE entscheidet, wer da unten ist, und der Hinweis nennt sie dir vor dem Auswurf. Tieferes Wasser hält seltenere und größere Fische.",
        ["GUIDE_STEP_5"]                     = "Warte auf den Biss und schlag rechtzeitig an. Dann kurbeln: Halt die Spannung aus dem Roten, zieh zur Seite wenn es dir gesagt wird und halt still, wenn der Fisch flüchtet.",
        ["GUIDE_STEP_6"]                     = "Angle weiter, bis die Auftragsfische in deiner Tasche sind, und verkauf den Fang dann im Shop.",
        ["GUIDE_TIP_1"]                      = "Höhere Level machen das Einholen leichter, erhöhen die Chance auf einen Extrafisch pro Wurf und verkürzen die Wartezeit auf einen Biss.",
        ["GUIDE_TIP_2"]                      = "Nichts ist unmöglich, nur unwahrscheinlich. Falsche Tiefe oder falscher Köder macht einen Fisch selten, nicht unerreichbar — ein Marlin im Flachwasser ist eine Geschichte wert.",
        ["GUIDE_TIP_5"]                      = "Ruten nutzen sich ab und brechen. Nimm eine zweite mit, wenn du weit vom Shop angelst.",
        ["GUIDE_TIP_3"]                      = "Du kannst andere einladen: Die ganze Gruppe arbeitet am selben Auftrag, und der Anführer wählt ihn.",
        ["GUIDE_TIP_4"]                      = "Der Reiter Statistiken führt die Tages- und Saisonwertung, und die besten drei werden bei jedem Zurücksetzen ausgezahlt.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "VOLL",
        ["NORMAL"]                           = "NORMAL",
        ["LOW"]                              = "NIEDRIG",
        ["CRITICAL"]                         = "KRITISCH",
        ["EMPTY"]                            = "LEER",
        ["WARNING_OXYGEN"]                   = "Deine Flasche ist fast leer — 10% übrig",
        ["GUIDE_TAB_BASICS"]                 = "Grundlagen",
        ["GUIDE_TAB_FISH"]                   = "Fische",
        ["GUIDE_TAB_WAYS"]                   = "Arten zu angeln",
        ["GUIDE_TAB_COOK"]                   = "Kochen",
        ["GUIDE_TAB_EVENTS"]                 = "Events",
        ["GUIDE_ZONES_ON_MAP"]               = "Turnierzonen auf deiner Karte",
        ["GUIDE_WAY_BOAT_T"]                 = "Ein Boot mieten",
        ["GUIDE_WAY_BOAT_1"]                 = "Die seltenen Fische leben im tiefen Wasser, und dorthin watet man nicht. Miete ein Boot im selben Panel wie die Aufträge.",
        ["GUIDE_WAY_BOAT_2"]                 = "Die Miete läuft auf Zeit und warnt dich vorher. Bring das Boot zum Steg zurück und du bekommst einen Teil des Preises wieder.",
        ["GUIDE_WAY_BOAT_3"]                 = "Wirf den Anker, bevor du auswirfst. Ein treibendes Boot zieht deine Schnur dorthin, wo du nicht gezielt hast.",
        ["GUIDE_WAY_TRAP_T"]                 = "Krabbenkörbe",
        ["GUIDE_WAY_TRAP_1"]                 = "Passives Angeln. Benutz einen Korb über tiefem Wasser: Der Käfig sinkt, eine Boje treibt darüber und auf deiner Karte erscheint eine Markierung.",
        ["GUIDE_WAY_TRAP_2"]                 = "Er wird nicht fertig, er füllt sich. Je länger er unten liegt, desto mehr hält er — bis zu einer Grenze. Wann du ihn hebst, entscheidest du.",
        ["GUIDE_WAY_TRAP_3"]                 = "Beim Heben kann der Käfig brechen. Ihn absichtlich abzubauen ist der sichere Weg, ihn zurückzubekommen.",
        ["GUIDE_WAY_TRAP_4"]                 = "Lässt du ihn zu lange, verrottet er mit allem darin. Du wirst vorher gewarnt.",
        ["GUIDE_WAY_NET_T"]                  = "Schleppnetze",
        ["GUIDE_WAY_NET_1"]                  = "Hier ist das Boot das Werkzeug. Benutz ein Netz am Steuer eines gemieteten Boots, und es geht über das Heck ins Wasser.",
        ["GUIDE_WAY_NET_2"]                  = "Ein Netz füllt sich über die GEFAHRENE STRECKE, nicht über die Zeit. Im Stand fängt es nichts, und es gibt eine ideale Geschwindigkeit.",
        ["GUIDE_WAY_NET_3"]                  = "Zu schnell oder in zu flachem Wasser reißt das Netz. Ein gerissenes Netz ist ein verlorenes Netz.",
        ["GUIDE_WAY_NET_4"]                  = "Ein Netz nimmt mit, was da ist, also fallen die Fische klein aus. Es geht um Menge, nicht um Trophäen.",
        ["GUIDE_WAY_SPEAR_T"]                = "Speerfischen",
        ["GUIDE_WAY_SPEAR_1"]                = "Das einzige Angeln IM Wasser, und es holt nur Haie. Keine Rute wird je einen an Land bringen.",
        ["GUIDE_WAY_SPEAR_2"]                = "Haie gibt es nur, solange du eine Jagd angenommen hast. Hol sie beim NPC, und eine Zone wird auf deiner Karte markiert.",
        ["GUIDE_WAY_SPEAR_3"]                = "Rechte Maustaste zum Zielen, linke zum Schießen. Jeder Schuss kostet einen Speer: Ein Fehlschuss ist weg, ein Treffer gibt ihn etwa jedes zweite Mal zurück.",
        ["GUIDE_WAY_SPEAR_4"]                = "Die Flasche ist optional. Ohne sie hast du deine eigene Luft, was knapp reicht — die Flasche kauft Komfort, keinen Zugang.",
        ["GUIDE_COOK_FIRE_T"]                = "Lagerfeuer",
        ["GUIDE_COOK_FIRE_1"]                = "Benutz ein Scheit für ein Feuer auf offenem Boden. Nicht auf der Straße, nicht drinnen, nicht auf dem Wasser: Sand und Gras will es.",
        ["GUIDE_COOK_FIRE_2"]                = "Interagiere mit dem Feuer, um einen Fisch aufzuspießen. Die Kamera senkt sich darauf, und die Maus dreht ihn.",
        ["GUIDE_COOK_FIRE_3"]                = "Dreh ihn immer weiter. Die den Flammen zugewandte Seite verkohlt, wenn du sie lässt, und genug Verkohltes verdirbt den Fisch trotzdem.",
        ["GUIDE_COOK_FIRE_4"]                = "Nimm ihn im grünen Fenster herunter und du hast einen gegarten Spieß. Lässt du ihn, verbrennt er: immer noch Essen, aber ein Viertel wert.",
        ["GUIDE_COOK_BOAT_T"]                = "Das Spießboot",
        ["GUIDE_COOK_BOAT_1"]                = "Ein Sardinengrill auf einem gestrandeten Boot, den du im Rucksack trägst. Stell ihn auf festen Boden und du stehst hinter der Theke.",
        ["GUIDE_COOK_BOAT_2"]                = "Alle rohen Spieße, die du trägst, erscheinen im Ständer daneben. Zieh einen auf die Glut, Rechtsklick zum Wenden, und nimm ihn herunter wenn er fertig ist.",
        ["GUIDE_COOK_BOAT_3"]                = "Klick auf die Glut, um von oben draufzuschauen, und daneben, um dich wieder aufzurichten. Ziehen geht nur aus der Nahansicht.",
        ["GUIDE_COOK_BOAT_4"]                = "Kundschaft kommt und will Spieße. Zieh ihnen einen fertigen hin, um ihn zu verkaufen, bevor sie das Warten satt haben.",
        ["GUIDE_EV_TOURN_T"]                 = "Turniere",
        ["GUIDE_EV_TOURN_1"]                 = "Ein Wasserabschnitt öffnet für eine Weile, und alle die darin angeln werden gewertet. Zwei Tafeln: der schwerste einzelne Fisch und die meisten Fische.",
        ["GUIDE_EV_TOURN_2"]                 = "Die besten drei jeder Tafel werden am Ende ausgezahlt. Über den Kartenknopf oben siehst du alle Zonen, in denen eines starten kann.",
        ["GUIDE_EV_TOURN_3"]                 = "Es zählt nur, was du innerhalb des Kreises fängst, und nur während es läuft.",
        ["GUIDE_EV_GOLD_T"]                  = "Goldene Zonen",
        ["GUIDE_EV_GOLD_1"]                  = "Ab und zu fängt ein Stück offenes Wasser deutlich besser. Ein goldener Stern erscheint auf der Karte und alle werden benachrichtigt.",
        ["GUIDE_EV_GOLD_2"]                  = "Niemand tritt gegeneinander an und niemand verliert. Leerzüge werden seltener und die guten Fische kommen öfter, solange es dauert.",
        ["GUIDE_EV_GOLD_3"]                  = "Körbe und Netze darin bekommen dasselbe, es lohnt sich also, auch die Ausrüstung umzusetzen.",
        ["GUIDE_EV_CREW_T"]                  = "In der Gruppe angeln",
        ["GUIDE_EV_CREW_1"]                  = "Lad Leute in deiner Nähe ein, und die ganze Gruppe arbeitet am selben Auftrag. Der Anführer wählt ihn.",
        ["GUIDE_EV_CREW_2"]                  = "Was jeder fängt, zählt für den Auftrag, und am Ende werden alle bezahlt.",
        ["GUIDE_EV_RANK_T"]                  = "Ranglisten",
        ["GUIDE_EV_RANK_1"]                  = "Der Reiter Statistiken führt eine Tages- und eine Saisontafel. Die besten drei werden bei jedem Zurücksetzen ausgezahlt.",
        ["GUIDE_EV_RANK_2"]                  = "Die Erfolge stehen daneben: jede gefangene Art, gelandete Trophäen und zurückgesetzte Fische.",
        ["FOODBOAT_NO_ORDER"]                = "Die Person hat nichts bestellt",
        ["FOODBOAT_BUYER_GONE"]              = "Sie ist nicht mehr da",
        ["FOODBOAT_BUYER_FULL"]              = "In ihre Tasche passt es nicht",
        ---@Admin settings panel
        ["ADMIN_SEARCH"]                     = "Alle Einstellungen durchsuchen…",
