        ["FOODBOAT_HINT_DROP"]              = "Отпустите над свободным местом",
        ["FOODBOAT_FOOT_VIEW"]              = "сменить вид",
        ["FOODBOAT_FOOT_LEAVE"]             = "свернуть",
        ["FOODBOAT_PROMPT"]                 = "Встаньте за прилавок",
        ["FOODBOAT_PACKED"]                 = "Вы свернули лавку.",
        ["FOODBOAT_NO_SKEWERS"]             = "У вас нет сырых шпажек.",
        ["FOODBOAT_BAD_GROUND"]             = "Здесь нет места для лавки.",
        ["FOODBOAT_NO_PROP"]                = "Лодка не загрузилась.",
        ["FOODBOAT_TUNER_NEEDS_BOAT"]       = "Сначала поставьте лодку.",
        ["FOODBOAT_TUNER_DONE"]             = "Значения выведены в консоль (F8).",
        ["COOK_RUINED_HINT"]                = "Испорчено — %s, чтобы снять",
        ["COOK_TURN_METER"]                 = "Крутить",
