        ["COOK_TAKE_HINT"]                  = "%s — снять с огня",
        ["COOK_HEAT_HINT"]                  = "Держите над огнём",
        ["COOK_CHARRING"]                   = "Подгорает с одной стороны",
        ["COOK_TOOK_RAW"]                   = "Сняли слишком рано — ещё сырое.",
        ["COOK_TOOK_COOKED"]                = "Прожарено как надо. Отличный шампур.",
        ["COOK_TOOK_BURNT"]                 = "Передержали. Всё сгорело.",
        ["COOK_LEFT_FIRE"]                  = "Вы отошли от костра.",
        ["COOK_ALREADY"]                    = "У вас уже что-то на огне.",
        ["COOK_NO_FISH"]                    = "Этого у вас больше нет.",
        ["COOK_FAILED"]                     = "Это не приготовилось.",
        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "Рыбалка — это одно непрерывное занятие, а не набор отдельных задач: берёшь заказ, ловишь то, что в нём указано, остальное продаёшь. Ниже весь цикл, а под ним — рыба, которую он может принести.",
        ["GUIDE_STEP_1"]                     = "Выбери заказ в этой панели. В нём указана нужная рыба, требуемый уровень и оплата.",
        ["GUIDE_STEP_2"]                     = "Сначала закупись в магазине. По-настоящему нужна только удочка, но крючки, катушки, лески и наживка облегчают всё.",
        ["GUIDE_STEP_3"]                     = "Открой ящик и поставь снасти. Наживка никогда не обязательна: она лишь делает поклёвку любящей её рыбы гораздо вероятнее, и у каждой рыбы ниже указана своя.",
        ["GUIDE_STEP_4"]                     = "Иди к воде и забрасывай лицом к ней. Кто внизу — решает ГЛУБИНА, и подсказка называет её до заброса. Глубже — реже и крупнее рыба.",
        ["GUIDE_STEP_5"]                     = "Дождись поклёвки и подсеки вовремя. Затем вываживай: держи натяжение вне красной зоны, тяни в сторону когда скажут и держи ровно, пока рыба уходит.",
        ["GUIDE_STEP_6"]                     = "Лови, пока рыба из заказа не окажется в сумке, потом продай улов в магазине и получи деньги.",
        ["GUIDE_TIP_1"]                      = "Повышение уровня облегчает вываживание, повышает шанс лишней рыбы за заброс и сокращает ожидание поклёвки.",
        ["GUIDE_TIP_2"]                      = "Невозможного нет, есть маловероятное. Не та глубина или не та наживка делают рыбу редкой, а не недосягаемой: марлин на мелководье — история, которую стоит рассказать.",
        ["GUIDE_TIP_5"]                      = "Удочки изнашиваются и ломаются. Бери запасную, если ловишь далеко от магазина.",
        ["GUIDE_TIP_3"]                      = "Можно приглашать других: вся группа работает над одним заказом, а выбирает его лидер.",
        ["GUIDE_TIP_4"]                      = "Вкладка «Статистика» ведёт дневной и сезонный рейтинги, и тройка лучших получает выплату при каждом сбросе.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "ПОЛНЫЙ",
        ["NORMAL"]                           = "НОРМА",
        ["LOW"]                              = "МАЛО",
        ["CRITICAL"]                         = "КРИТИЧНО",
        ["EMPTY"]                            = "ПУСТО",
        ["WARNING_OXYGEN"]                   = "Баллон почти пуст — осталось 10%",
        ["GUIDE_TAB_BASICS"]                 = "Основы",
        ["GUIDE_TAB_FISH"]                   = "Рыба",
        ["GUIDE_TAB_WAYS"]                   = "Способы ловли",
        ["GUIDE_TAB_COOK"]                   = "Готовка",
        ["GUIDE_TAB_EVENTS"]                 = "События",
        ["GUIDE_ZONES_ON_MAP"]               = "Зоны турниров на карте",
        ["GUIDE_WAY_BOAT_T"]                 = "Аренда лодки",
        ["GUIDE_WAY_BOAT_1"]                 = "Редкая рыба живёт на глубине, а туда вброд не дойти. Арендуй лодку в той же панели, где берёшь заказы.",
        ["GUIDE_WAY_BOAT_2"]                 = "У аренды есть время, и тебя предупредят до конца. Верни лодку к причалу — получишь часть денег обратно.",
        ["GUIDE_WAY_BOAT_3"]                 = "Брось якорь перед забросом. Дрейфующая лодка уводит леску туда, куда ты не целился.",
        ["GUIDE_WAY_TRAP_T"]                 = "Крабовые ловушки",
        ["GUIDE_WAY_TRAP_1"]                 = "Пассивная ловля. Используй ловушку над глубокой водой: клетка тонет, сверху остаётся буй, а на карте появляется метка.",
        ["GUIDE_WAY_TRAP_2"]                 = "Она не заканчивается, а наполняется. Чем дольше стоит, тем больше в ней, до предела — когда поднимать, решаешь ты.",
        ["GUIDE_WAY_TRAP_3"]                 = "При подъёме клетка может сломаться. Разобрать её намеренно — надёжный способ вернуть.",
        ["GUIDE_WAY_TRAP_4"]                 = "Оставишь надолго — сгниёт вместе со всем содержимым. Об этом предупредят заранее.",
        ["GUIDE_WAY_NET_T"]                  = "Тралы",
        ["GUIDE_WAY_NET_1"]                  = "Здесь инструмент — лодка. Используй сеть за штурвалом арендованной лодки, и она уйдёт за корму.",
        ["GUIDE_WAY_NET_2"]                  = "Сеть наполняется по ПРОЙДЕННОМУ ПУТИ, а не по времени. На месте она не берёт ничего, и есть скорость, на которой она работает лучше всего.",
        ["GUIDE_WAY_NET_3"]                  = "Слишком быстро или на мелководье — сеть рвётся. Порванная сеть — потерянная сеть.",
        ["GUIDE_WAY_NET_4"]                  = "Сеть берёт что есть, поэтому рыба выходит мелкая. Это количество, а не трофеи.",
        ["GUIDE_WAY_SPEAR_T"]                = "Подводная охота",
        ["GUIDE_WAY_SPEAR_1"]                = "Единственная ловля В воде, и берёт она только акул. Ни одна удочка их не вытащит.",
        ["GUIDE_WAY_SPEAR_2"]                = "Акулы существуют, только пока принята охота. Возьми её у NPC — на карте отметится зона.",
        ["GUIDE_WAY_SPEAR_3"]                = "Правая кнопка — прицел, левая — выстрел. Каждый выстрел тратит гарпун: промах теряется, попадание возвращает его примерно в половине случаев.",
        ["GUIDE_WAY_SPEAR_4"]                = "Баллон не обязателен. Без него у тебя свои лёгкие, чего едва хватает — баллон даёт удобство, а не доступ.",
        ["GUIDE_COOK_FIRE_T"]                = "Костры",
        ["GUIDE_COOK_FIRE_1"]                = "Используй полено, чтобы развести костёр на открытой земле. Не на асфальте, не в помещении, не на воде: нужен песок или трава.",
        ["GUIDE_COOK_FIRE_2"]                = "Взаимодействуй с огнём, чтобы насадить рыбу на шампур. Камера опустится на него, а мышь будет его вращать.",
        ["GUIDE_COOK_FIRE_3"]                = "Верти его. Сторона, обращённая к пламени, обугливается, если её оставить, и достаточное обугливание портит рыбу в любом случае.",
        ["GUIDE_COOK_FIRE_4"]                = "Сними в зелёном окне — получишь готовый шампур. Оставишь — сгорит: это всё ещё еда, но вчетверо дешевле.",
        ["GUIDE_COOK_BOAT_T"]                = "Лодка-мангал",
        ["GUIDE_COOK_BOAT_1"]                = "Мангал для сардин на вытащенной на берег лодке, который ты носишь в рюкзаке. Поставь его на твёрдую землю — и окажешься за прилавком.",
        ["GUIDE_COOK_BOAT_2"]                = "Все сырые шампуры, что при тебе, появятся на стойке рядом. Перетащи один на угли, правая кнопка — перевернуть, и сними, когда будет готов.",
        ["GUIDE_COOK_BOAT_3"]                = "Нажми на угли, чтобы посмотреть на них сверху, и в сторону, чтобы выпрямиться. Перетаскивать можно только с ближнего вида.",
        ["GUIDE_COOK_BOAT_4"]                = "Подходят клиенты и просят шампуры. Перетащи им готовый, чтобы продать, пока они не устали ждать.",
        ["GUIDE_EV_TOURN_T"]                 = "Турниры",
        ["GUIDE_EV_TOURN_1"]                 = "Участок воды открывается на время, и всех, кто ловит внутри, оценивают. Две таблицы: самая тяжёлая рыба и наибольшее количество.",
        ["GUIDE_EV_TOURN_2"]                 = "Тройка лучших в каждой таблице получает выплату по окончании. Кнопкой карты выше можно увидеть все зоны, где турнир может открыться.",
        ["GUIDE_EV_TOURN_3"]                 = "Засчитывается только то, что поймано внутри круга, и только пока он активен.",
        ["GUIDE_EV_GOLD_T"]                  = "Золотые зоны",
        ["GUIDE_EV_GOLD_1"]                  = "Время от времени участок открытой воды начинает ловиться гораздо лучше. На карте появляется золотая звезда, и всех оповещают.",
        ["GUIDE_EV_GOLD_2"]                  = "Никто не соревнуется и никто не проигрывает. Пустых забросов меньше, а хорошая рыба идёт чаще, пока это длится.",
        ["GUIDE_EV_GOLD_3"]                  = "Ловушки и сети внутри получают то же самое, так что стоит переставить и снасти, а не только прийти самому.",
        ["GUIDE_EV_CREW_T"]                  = "Ловля группой",
        ["GUIDE_EV_CREW_1"]                  = "Приглашай тех, кто рядом, и вся группа работает над одним заказом. Выбирает его лидер.",
        ["GUIDE_EV_CREW_2"]                  = "Улов каждого идёт в зачёт заказа, и по завершении платят всем.",
        ["GUIDE_EV_RANK_T"]                  = "Рейтинги",
        ["GUIDE_EV_RANK_1"]                  = "Вкладка «Статистика» ведёт дневную и сезонную таблицы. Тройка лучших получает выплату при каждом сбросе.",
        ["GUIDE_EV_RANK_2"]                  = "Рядом идут достижения: каждый пойманный вид, взятые трофеи и отпущенная рыба.",
        ["FOODBOAT_NO_ORDER"]                = "Этот игрок ничего не заказывал",
        ["FOODBOAT_BUYER_GONE"]              = "Его здесь больше нет",
        ["FOODBOAT_BUYER_FULL"]              = "В его сумку это не влезет",
