        ---@Added by the translation audit
        ["GUIDE_INTRO"]                      = "Balıkçılık ayrı görevler dizisi değil, tek ve sürekli bir iştir: bir görev alırsın, istediğini yakalarsın, gerisini satarsın. Aşağıda döngünün tamamı, altında da sana verebileceği balıklar var.",
        ["GUIDE_STEP_1"]                     = "Bu panelden bir görev seç. Hangi balığı getireceğini, gereken seviyeyi ve ödemeyi söyler.",
        ["GUIDE_STEP_2"]                     = "Önce Dükkândan stok yap. Gerçekten şart olan tek şey olta, ama iğneler, makaralar, misinalar ve yemler her şeyi kolaylaştırır.",
        ["GUIDE_STEP_3"]                     = "Takım kutusunu aç ve ekipmanını tak. Yem hiçbir zaman zorunlu değildir: sadece onu seven balığın vurma ihtimalini çok artırır ve aşağıda her balığın favorisi yazar.",
        ["GUIDE_STEP_4"]                     = "Suyun kenarına git ve suya dönük at. Aşağıda kimin olduğuna DERİNLİK karar verir ve uyarı bunu atıştan önce söyler. Daha derin su, daha nadir ve daha büyük balık demektir.",
        ["GUIDE_STEP_5"]                     = "Vuruşu bekle ve zamanında tasla. Sonra sar: gerginliği kırmızının dışında tut, söylendiğinde yana çek ve balık kaçarken sabit dur.",
        ["GUIDE_STEP_6"]                     = "Görevdeki balıklar çantana girene kadar devam et, sonra avı Dükkânda satıp parayı al.",
        ["GUIDE_TIP_1"]                      = "Seviye atlamak sarmayı kolaylaştırır, atış başına fazladan balık şansını artırır ve vuruş beklemesini kısaltır.",
        ["GUIDE_TIP_2"]                      = "Hiçbir şey imkânsız değildir, sadece ihtimali düşüktür. Yanlış derinlik ya da yanlış yem bir balığı nadir yapar, ulaşılmaz değil: sığ suda bir marlin anlatılacak bir hikâyedir.",
        ["GUIDE_TIP_5"]                      = "Oltalar yıpranır ve kırılır. Dükkândan uzakta balık tutacaksan yedek taşı.",
        ["GUIDE_TIP_3"]                      = "Başkalarını davet edebilirsin: tüm ekip aynı görevi yapar ve görevi lider seçer.",
        ["GUIDE_TIP_4"]                      = "İstatistikler sekmesi günlük ve sezonluk sıralamayı tutar, her sıfırlamada ilk üç ödeme alır.",
        ["PSI"]                              = "PSI",
        ["FULL"]                             = "DOLU",
        ["NORMAL"]                           = "NORMAL",
        ["LOW"]                              = "DÜŞÜK",
        ["CRITICAL"]                         = "KRİTİK",
        ["EMPTY"]                            = "BOŞ",
        ["WARNING_OXYGEN"]                   = "Tüpün neredeyse boş — %10 kaldı",
        ["GUIDE_TAB_BASICS"]                 = "Temeller",
        ["GUIDE_TAB_FISH"]                   = "Balıklar",
        ["GUIDE_TAB_WAYS"]                   = "Avlanma yolları",
        ["GUIDE_TAB_COOK"]                   = "Pişirme",
        ["GUIDE_TAB_EVENTS"]                 = "Etkinlikler",
        ["GUIDE_ZONES_ON_MAP"]               = "Haritandaki turnuva bölgeleri",
        ["GUIDE_WAY_BOAT_T"]                 = "Tekne kiralamak",
        ["GUIDE_WAY_BOAT_1"]                 = "Nadir balıklar derin suda yaşar ve oraya yürüyerek gidilmez. Görevleri aldığın panelden tekne kirala.",
        ["GUIDE_WAY_BOAT_2"]                 = "Kiralamanın süresi vardır ve bitmeden uyarılırsın. Tekneyi iskeleye geri getirirsen ücretin bir kısmını geri alırsın.",
        ["GUIDE_WAY_BOAT_3"]                 = "Atış yapmadan önce demir at. Sürüklenen bir tekne misinayı nişan almadığın yere götürür.",
        ["GUIDE_WAY_TRAP_T"]                 = "Yengeç kapanları",
        ["GUIDE_WAY_TRAP_1"]                 = "Pasif avlanma. Derin suyun üzerinde bir kapan kullan: kafes batar, üstünde bir şamandıra kalır ve haritanda bir işaret belirir.",
        ["GUIDE_WAY_TRAP_2"]                 = "Bitmez, dolar. Ne kadar uzun kalırsa o kadar çok tutar, bir sınıra kadar — ne zaman çekeceğine sen karar verirsin.",
        ["GUIDE_WAY_TRAP_3"]                 = "Çekmek kafesi kırabilir. Bilerek sökmek onu geri almanın daha güvenli yoludur.",
        ["GUIDE_WAY_TRAP_4"]                 = "Çok uzun bırakırsan içindekilerle birlikte çürür. Bu olmadan önce uyarılırsın.",
        ["GUIDE_WAY_NET_T"]                  = "Trol ağları",
        ["GUIDE_WAY_NET_1"]                  = "Burada araç teknedir. Kiralık bir teknenin dümenindeyken ağ kullan, kıçtan suya iner.",
        ["GUIDE_WAY_NET_2"]                  = "Ağ süreye göre değil, KAT EDİLEN MESAFEYE göre dolar. Dururken hiçbir şey almaz ve en verimli olduğu bir hız vardır.",
        ["GUIDE_WAY_NET_3"]                  = "Çok hızlı gidersen ya da fazla sığ suda çekersen ağ yırtılır. Yırtılan ağ kaybedilen ağdır.",
        ["GUIDE_WAY_NET_4"]                  = "Ağ orada ne varsa toplar, bu yüzden balıklar küçük çıkar. Bu miktar meselesidir, kupa değil.",
        ["GUIDE_WAY_SPEAR_T"]                = "Zıpkınla avlanma",
        ["GUIDE_WAY_SPEAR_1"]                = "Suyun İÇİNDE yaptığın tek avlanma ve sadece köpek balığı tutar. Hiçbir olta bir tanesini çıkaramaz.",
        ["GUIDE_WAY_SPEAR_2"]                = "Köpek balıkları yalnızca kabul edilmiş bir av varken vardır. NPC'den al, haritanda bir bölge işaretlenir.",
        ["GUIDE_WAY_SPEAR_3"]                = "Nişan almak için sağ tık, ateş etmek için sol. Her atış bir zıpkın harcar: ıskalarsan gider, isabet ettirirsen aşağı yukarı yarı yarıya geri alırsın.",
        ["GUIDE_WAY_SPEAR_4"]                = "Dalış tüpü isteğe bağlıdır. Tüpsüz kendi ciğerlerin var, ki ancak yeter — tüp erişim değil, rahatlık satın alır.",
        ["GUIDE_COOK_FIRE_T"]                = "Kamp ateşi",
        ["GUIDE_COOK_FIRE_1"]                = "Açık zeminde ateş yakmak için bir kütük kullan. Asfaltta değil, kapalı alanda değil, suda değil: kum ya da çim ister.",
        ["GUIDE_COOK_FIRE_2"]                = "Şişe balık geçirmek için ateşle etkileşime gir. Kamera üzerine iner ve fare onu çevirir.",
        ["GUIDE_COOK_FIRE_3"]                = "Çevirmeye devam et. Aleve bakan taraf bırakırsan kömürleşir ve yeterince kömürleşme balığı yine de mahveder.",
        ["GUIDE_COOK_FIRE_4"]                = "Yeşil aralıkta çıkarırsan pişmiş bir şiş elde edersin. Bırakırsan yanar: hâlâ yemektir ama dörtte biri kadar eder.",
        ["GUIDE_COOK_BOAT_T"]                = "Şiş teknesi",
        ["GUIDE_COOK_BOAT_1"]                = "Sırt çantanda taşıdığın, karaya çekilmiş bir teknenin üstündeki sardalya ızgarası. Sağlam zemine bırak ve tezgâhın arkasında bulursun kendini.",
        ["GUIDE_COOK_BOAT_2"]                = "Taşıdığın bütün çiğ şişler yanındaki askıda belirir. Birini kora sürükle, çevirmek için sağ tık, hazır olunca çıkar.",
        ["GUIDE_COOK_BOAT_3"]                = "Kora tıklayarak yukarıdan bak, dışına tıklayarak doğrul. Sürükleme sadece yakın görünümde yapılır.",
        ["GUIDE_COOK_BOAT_4"]                = "Müşteriler gelip şiş ister. Beklemekten sıkılmadan önce pişmiş bir tanesini üzerlerine sürükleyip sat.",
        ["GUIDE_EV_TOURN_T"]                 = "Turnuvalar",
        ["GUIDE_EV_TOURN_1"]                 = "Bir su alanı bir süreliğine açılır ve içinde avlanan herkes puanlanır. İki tablo: en ağır tek balık ve en çok balık.",
        ["GUIDE_EV_TOURN_2"]                 = "Her tablonun ilk üçü kapanışta ödeme alır. Yukarıdaki harita düğmesiyle turnuvanın açılabileceği tüm bölgeleri görebilirsin.",
        ["GUIDE_EV_TOURN_3"]                 = "Sadece çemberin içinde yakaladıkların ve sadece etkinken sayılır.",
        ["GUIDE_EV_GOLD_T"]                  = "Altın bölgeler",
        ["GUIDE_EV_GOLD_1"]                  = "Arada bir açık suda bir alan çok daha iyi vermeye başlar. Haritada altın bir yıldız belirir ve herkese haber verilir.",
        ["GUIDE_EV_GOLD_2"]                  = "Kimse yarışmaz ve kimse kaybetmez. Sürdüğü sürece boş atışlar azalır ve iyi balıklar daha sık çıkar.",
        ["GUIDE_EV_GOLD_3"]                  = "İçindeki kapanlar ve ağlar da aynı muameleyi görür, yani sadece kendin değil ekipmanını da taşımaya değer.",
        ["GUIDE_EV_CREW_T"]                  = "Ekiple avlanmak",
        ["GUIDE_EV_CREW_1"]                  = "Yakınındakileri davet et, tüm ekip aynı görevi yapar. Görevi lider seçer.",
        ["GUIDE_EV_CREW_2"]                  = "Herkesin yakaladığı göreve sayılır ve iş bitince hepsi ödeme alır.",
        ["GUIDE_EV_RANK_T"]                  = "Sıralamalar",
        ["GUIDE_EV_RANK_1"]                  = "İstatistikler sekmesi günlük ve sezonluk bir tablo tutar. Her sıfırlamada ilk üç ödeme alır.",
        ["GUIDE_EV_RANK_2"]                  = "Başarımlar da yanında: yakalanan her tür, çıkarılan kupalar ve geri bırakılan balıklar.",
        ["FOODBOAT_NO_ORDER"]                = "O kişi bir şey sipariş etmedi",
        ["FOODBOAT_BUYER_GONE"]              = "Artık burada değil",
