--- English fallback.
---
--- Every language above is filled in from 'en' for any key it is missing, so a
--- new string only has to be written once to stop other languages showing the
--- raw key on screen. Translate it properly in each block whenever you can —
--- this is a safety net, not a substitute.
do
    local reference = Config.Languages['en']

    for code, language in pairs(Config.Languages) do
        if code ~= 'en' and type(language) == 'table' then
            for key, value in pairs(reference) do
                if language[key] == nil then language[key] = value end
            end
        end
    end
end
